        "c11a799b86594182b747ec8d0974ff70": {
          "id": "c11a799b86594182b747ec8d0974ff70",
          "name": "Get User Location & Location Config",
          "script": "(function execute() {\n\n    //TODO: in all flows convert inputs to lower case. \n    if(null!= vaInputs.badge_type &&  \"\"!= vaInputs.badge_type){\n        vaVars.badge_type= vaInputs.badge_type;\n    }else{\n        vaInputs.badge_type = \"\";\n        vaVars.badge_type= \"\";\n    }\n\n    var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')\n    idenlocationGr.addQuery('identity',vaInputs.user_sys_id);\n    idenlocationGr.query();\n    var location = \"\";\n    if(idenlocationGr.next()){\n        location = idenlocationGr.location;\n        vaVars.user_location = location;\n    }\n     //TODO : will use guardian Location administrator config.\n    var dtInputs = {};\n    dtInputs.user_location = vaVars.user_location;\n    var result = new GuardianAIAgentHelper().getDTConfigs(\"a57ddb4833083650bf1221382e5c7b7e\",dtInputs);\n    gs.info(\"DT Result Mob Cred : \"+JSON.stringify(result));\n    vaVars.location_mobile_cred_enabled = result.MC_SUPPORT;\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "4714693e19b843dfa3edff4a07f9f956": {
          "id": "4714693e19b843dfa3edff4a07f9f956",
          "name": "get DT Badge Config",
          "script": "(function execute() {\n    var dtInputs = {};\n    dtInputs.user_location = vaVars.user_location;\n    dtInputs.user_type = vaInputs.user_type_sys_id;\n    if(null != vaInputs.badge_issue_type && \"\" != vaInputs.badge_issue_type && vaInputs.badge_issue_type.indexOf(\"plastic\") > -1){\n        if(null != vaInputs.badge_type_input_choice && \"\" != vaInputs.badge_type_input_choice ){\n            dtInputs.badge_type = vaInputs.badge_type_input_choice;\n        } else {\n            dtInputs.badge_type = vaVars.badge_type;\n        }\n    } else if(null != vaInputs.badge_issue_type && \"\" != vaInputs.badge_issue_type && vaInputs.badge_issue_type.indexOf(\"mobile\") > -1){\n        dtInputs.badge_type = \"mobile credentials\";\n    } else {\n        if(vaVars.badge_type != \"\"){\n            dtInputs.badge_type = vaVars.badge_type;\n        }else{\n            dtInputs.badge_type = vaInputs.badge_type_input_choice;\n        }\n    }\n     // Final badge_typs is in dtInputs.badge_type // DON'T DARE TO TOUCH UNLESS TESTED DEEPLY.\n    dtInputs.badge_action = \"assign\";\n    var result = new GuardianAIAgentHelper().getDTConfigs(\"0d37c78833843650bf1221382e5c7bc7\",dtInputs);\n    gs.info(\"DT Result : \"+JSON.stringify(result));\n// {\n//   \"SUB_TYPE\": \"\",\n//   \"VALID_FROM\": \"CURRENT\",\n//   \"VALID_TO\": \"PROMPT\",\n//   \"DEFAULT_ACCESS\": \"true\",\n//   \"APPROVAL\": \"false\",\n//   \"DEACTIVATE_EXISTING\": \"false\",\n//   \"COPY_ACCESS\": \"false\",\n//   \"DEFAULT_STATUS\": \"2a7f0ed51bbc8210759455342a4bcbe9\",\n//   \"ASSIGNMENT_TYPE\": \"Auto\",\n//   \"SYS_ID\": \"2c4b76f22bf72e10d4dffd74ce91bfd0\"\n// }\n    //default system\n    var locationAdminGr = new GlideRecordSecure('x_aleen_snguardian_badge_office');\n    locationAdminGr.addQuery('locationsLIKE'+vaVars.user_location);\n    locationAdminGr.orderBy('order');\n    locationAdminGr.query();\n    if(locationAdminGr.next()){\n        vaVars.default_system = locationAdminGr.system;\n    }\n\n    //default access\n    if(vaVars.user_location){\n        var accessList = [];\n        var accessLocationGr = new GlideRecordSecure('x_aleen_snguardian_access_location');\n        accessLocationGr.addQuery('location', vaVars.user_location);\n        accessLocationGr.addQuery('is_default', true);\n        accessLocationGr.query();\n        while (accessLocationGr.next()) {\n            var accessLevel = accessLocationGr.access_level.toString(); // Convert to string\n            if (accessList.indexOf(accessLevel) === -1) {\n                accessList.push(accessLevel);\n            }\n        }\n        vaVars.default_access = accessList.join();             \n    }\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
