              },
              "applicability": {
                "mode": "script",
                "value": "(function execute() {\n    if(vaVars.location_mobile_cred_enabled){\n        if(vaVars.location_mobile_cred_enabled == \"false\"){\n           return false;\n        }\n        var badgeTypeData = vaVars.badge_type;\n         var badgeTypeInputData = vaInputs.badge_type;\n        gs.info(\"SHOW AAAAAAAAAAAAA MC_INPUT: IN \"+ badgeTypeData );\n        if(badgeTypeData == \"\" && badgeTypeInputData == \"\"){\n             gs.info(\"SHOW MC_INPUT: IN SIDE  AAAAAAAAAAAAAAAAAAAAAA\"+ badgeTypeData );\n            return true;\n        }\n        if(badgeTypeData.indexOf(\"perm\") > -1 ||  badgeTypeData.indexOf(\"temp\") > -1 ){\n             gs.info(\"SHOW MC_INPUT: IN SIDE  BBBBBBBBBBBBBBBBBBB\"+ badgeTypeData );\n            return true;\n        }\n         gs.info(\"SHOW MC_INPUT: RETURNINGAAAAAAAAAAAAAAAAAAAAAA \"+ badgeTypeData );\n        \n\n    }\n     gs.info(\"SHOW MC_INPUT: RETURNING  CCCC \" );\n     return false;\n\n})()\n"
